CREATE TABLE IF NOT EXISTS claims (id BIGSERIAL PRIMARY KEY, policy_id BIGINT NOT NULL, status VARCHAR(20) NOT NULL, district VARCHAR(20) NOT NULL, incident_at TIMESTAMP WITH TIME ZONE NOT NULL, kaiju_class INT NOT NULL, description TEXT NOT NULL, filed_at TIMESTAMP WITH TIME ZONE NOT NULL, CONSTRAINT fk_claims_policy_id__id FOREIGN KEY (policy_id) REFERENCES policies(id) ON DELETE RESTRICT ON UPDATE RESTRICT);
CREATE SEQUENCE IF NOT EXISTS claims_id_seq START WITH 1 MINVALUE 1 MAXVALUE 9223372036854775807;